.darma-loader-tw-sparkle-stars { position: relative; display: inline-block; width: var(--loader-size, 64px); height: var(--loader-size, 64px); }
.darma-loader-tw-sparkle-stars span { position: absolute; background: var(--loader-color, #a855f7); clip-path: polygon(50% 0, 61% 39%, 100% 50%, 61% 61%, 50% 100%, 39% 61%, 0 50%, 39% 39%); animation: darma-loader-tw-sparkle-stars-twTwinkle calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-tw-sparkle-stars span:nth-child(1) { left: 6%; top: 10%; width: 42%; height: 42%; }
.darma-loader-tw-sparkle-stars span:nth-child(2) { right: 4%; top: 30%; width: 30%; height: 30%; animation-delay: calc(var(--loader-speed, 1s) * .35); }
.darma-loader-tw-sparkle-stars span:nth-child(3) { left: 32%; bottom: 4%; width: 24%; height: 24%; animation-delay: calc(var(--loader-speed, 1s) * .7); }
@keyframes darma-loader-tw-sparkle-stars-twTwinkle { 0%, 100% { transform: scale(.35) rotate(0deg); opacity: .2; } 50% { transform: scale(1) rotate(45deg); opacity: 1; } }

